import {domainStats,domainEvidence} from './analysis.js';
import {domains} from './reporting.js';
import {esc,csv,download} from './core.js';
const templates=[
 ['Prendre la main sur l’ordinateur','Saisir, corriger et retrouver une fenêtre sans guidage.','Écrire une courte invitation, corriger deux mots et alterner entre deux fenêtres.','Ajouter une mise en forme et des raccourcis clavier.','Refaire une saisie et un changement de fenêtre ; observer D1 et D2.'],
 ['Organiser et retrouver ses documents','Enregistrer puis retrouver un document au bon endroit.','Créer un dossier, y enregistrer une copie et retrouver un téléchargement.','Organiser des sous-dossiers et préparer une copie de sauvegarde.','Retrouver un fichier avec un autre nom ; observer D3 et D5.'],
 ['Chercher une information fiable','Trouver une information en expliquant le choix de la source.','Chercher un horaire et comparer deux pages en regardant leur auteur et leur date.','Comparer des informations contradictoires et formuler une vérification.','Nouvelle recherche ; observer D4 et discuter une variante de S3.'],
 ['Envoyer un document par e-mail','Préparer destinataire, objet, message et pièce jointe.','Préparer un message d’exercice avec un document, puis relire avant validation.','Adapter destinataires et objet à une autre situation.','Préparer un second message sans aide ; observer D6.'],
 ['Protéger ses comptes et repérer les pièges','Identifier une demande suspecte et choisir une vérification sûre.','Comparer des messages fictifs et expliquer comment vérifier sans suivre leur lien.','Explorer les réglages de sécurité avec des exemples, sans partager de secrets.','Nouvelle situation de message pressant ; expliquer sa décision.'],
 ['Réussir une démarche en ligne','Repérer les informations demandées et corriger un formulaire.','Remplir un formulaire fictif, lire les erreurs et vérifier les pièces requises.','Préparer une liste de pièces et organiser leur rangement.','Nouveau formulaire fictif avec une erreur différente à corriger.'],
 ['Comprendre son smartphone','Choisir une connexion et ajuster une autorisation utile.','Repérer Wi-Fi et données mobiles, puis discuter les permissions d’une application.','Retrouver et ajuster des réglages de confidentialité.','Expliquer une permission et retrouver le réglage correspondant sur son appareil.'],
 ['Partager en maîtrisant son audience','Choisir les destinataires d’une publication et anticiper sa diffusion.','Comparer des audiences fictives et choisir ce que l’on accepte de partager.','Réviser des réglages de compte avec un accompagnement individuel.','Nouvelle situation de publication : justifier audience et précautions.'],
 ['Utiliser l’IA avec recul','Utiliser une réponse d’IA comme une proposition à vérifier.','Préparer une demande sans information sensible, puis relire et vérifier le résultat.','Comparer deux réponses et expliquer les limites constatées.','Repérer une information incertaine et proposer une vérification.']
];
export function normalizePlan(value){if(!value||value.version!==1||!Array.isArray(value.items)||value.items.length!==12)return null;const fields=['title','objective','activity','variant','check','rationale','people','notes'];return {version:1,generatedAt:typeof value.generatedAt==='string'?value.generatedAt:'',sample:Number.isSafeInteger(value.sample)?value.sample:0,items:value.items.map((x,i)=>Object.fromEntries([['id',String(i+1)],...fields.map(k=>[k,typeof x?.[k]==='string'?x[k].slice(0,2000):''])]))};}
export function buildPlan(ps){
 const stats=domainStats(ps);if(!stats.some(s=>s.evidence||s.requested))return null;
 const rank=(a,b)=>b.need-a.need||b.requested-a.requested||domains.indexOf(a.domain)-domains.indexOf(b.domain);
 const ordered=[...stats.slice(0,2),...stats.slice(2).sort(rank)];const reinforces=stats.filter(s=>s.need||s.requested).sort(rank).slice(0,2);
 // When few needs are documented, the extra slots consolidate prerequisites without inventing a measured difficulty.
 while(reinforces.length<2)reinforces.push(stats.find(s=>!reinforces.includes(s)));
 const make=(s,again=false)=>{const i=domains.indexOf(s.domain),t=templates[i],people=ps.filter(p=>{const e=domainEvidence(p,s.domain);return e.need||e.requested;});return {title:(again?'Réinvestir : ':'')+t[0],objective:again?'Transférer les acquis de ce domaine à une nouvelle tâche.':t[1],activity:again?'Reprendre une tâche de ce domaine avec un nouveau document ou contexte choisi par le groupe.':t[2],variant:t[3],check:t[4],rationale:`${s.need} / ${ps.length} personne(s) avec un besoin repéré ; ${s.requested} demande(s) ; ${s.missing} avec éléments manquants. ${!s.evidence?'Pas de résultat exploitable dans ce domaine : contenu à confirmer.':again?'Consolidation proposée, à confirmer selon les progrès.':'Proposition fondée sur les éléments disponibles, à valider.'}`,people:people.length?people.map(p=>p.name).join(', '):'À définir avec le groupe',notes:''};};
 const items=[...ordered.map(s=>make(s)),...reinforces.map(s=>make(s,true)),{title:'Bilan et projet personnel',objective:'Réaliser une tâche utile et rendre les progrès visibles.',activity:'Chaque personne choisit un petit projet lié à son objectif et le réalise avec une aide adaptée.',variant:'Associer plusieurs compétences dans un même projet.',check:'Reprendre quelques tâches comparables du diagnostic initial et noter le niveau d’aide.',rationale:'Clôture proposée pour tous ; comparer les mêmes gestes et conserver les conditions d’observation.',people:'Tout le groupe',notes:''}];
 const docs=ps.filter(p=>p.answers.interests?.includes('Documents et tableaux'));if(docs.length)items[10]={title:'Créer un document ou un tableau utile',objective:'Produire un document simple répondant à un besoin choisi.',activity:'Mettre en page un courrier ou construire un tableau simple avec des données fictives.',variant:'Améliorer la présentation et essayer un calcul simple dans un tableur.',check:'Créer un second document en expliquant les choix de mise en page.',rationale:docs.length+' demande(s) explicite(s). Ce domaine n’a pas été évalué en détail : commencer par une courte observation.',people:docs.map(p=>p.name).join(', '),notes:''};
 return normalizePlan({version:1,generatedAt:new Date().toISOString(),sample:ps.length,items});
}
export function planCsv(plan){return csv([['atelier','titre','objectif','activite','variante','verification','justification','participants_concernes','notes'],...plan.items.map((x,i)=>[i+1,x.title,x.objective,x.activity,x.variant,x.check,x.rationale,x.people,x.notes])]);}
export function mountPlan(box,session,ps,{save,onDirty}){
 let draft=normalizePlan(session.plan)||buildPlan(ps);if(!draft){box.innerHTML='<div class="card"><h2>Vos 12 ateliers</h2><p>La proposition apparaîtra dès qu’une réponse, une observation ou une envie sera disponible. Les seules activités manquantes ne permettent pas de déduire des besoins.</p></div>';return;}
 const fields=[['title','Titre'],['objective','Objectif concret'],['activity','Activité'],['variant','Variante plus avancée'],['check','Vérification des progrès'],['people','Participants concernés'],['notes','Vos notes']];
 function draw(){box.innerHTML=`<div class="card"><h2>Proposition de 12 ateliers</h2><p>Pré-requis ordinateur et fichiers en premier, puis domaines ordonnés par nombre de personnes avec un besoin repéré, puis par demandes. Deux séances de consolidation et un bilan complètent la trame. Ce choix est pédagogique et modifiable ; il ne classe pas les participants.</p><p>Calculée le ${esc(new Date(draft.generatedAt).toLocaleString('fr-FR'))} à partir de ${draft.sample} participant(s). ${session.plan?'Version sauvegardée : elle ne change pas automatiquement avec les nouveaux résultats.':'Proposition calculée : enregistrez vos adaptations pour les conserver.'}</p><div class="actions"><button id="plan-save">Enregistrer le programme</button><button class="secondary" id="plan-csv">Exporter le programme CSV</button><button class="secondary" id="plan-new">Recalculer avec les résultats actuels</button></div><p id="plan-status" role="status"></p></div>${draft.items.map((x,i)=>`<details class="card plan-item" ${i===0?'open':''}><summary>Atelier ${i+1} · ${esc(x.title)}</summary><p class="notice">${esc(x.rationale)}</p><div class="actions"><button class="small secondary" data-move="${i}|-1" ${i===0?'disabled':''}>Monter</button><button class="small secondary" data-move="${i}|1" ${i===11?'disabled':''}>Descendre</button></div>${fields.map(([k,label])=>`<label for="plan-${i}-${k}">${label}</label><textarea id="plan-${i}-${k}" data-plan-index="${i}" data-plan-key="${k}" maxlength="2000" rows="${k==='title'?1:2}">${esc(x[k])}</textarea>`).join('')}</details>`).join('')}`;
 box.querySelectorAll('[data-plan-key]').forEach(el=>el.oninput=()=>{draft.items[Number(el.dataset.planIndex)][el.dataset.planKey]=el.value;onDirty(true);box.querySelector('#plan-status').textContent='Modifications à enregistrer.';});
 box.querySelectorAll('[data-move]').forEach(el=>el.onclick=()=>{const [i,delta]=el.dataset.move.split('|').map(Number);[draft.items[i],draft.items[i+delta]]=[draft.items[i+delta],draft.items[i]];onDirty(true);draw();box.querySelector('#plan-status').textContent='Ordre modifié, à enregistrer.';});
 box.querySelector('#plan-new').onclick=()=>{if(!confirm('Recalculer remplacera cette proposition et vos modifications. Continuer ?'))return;const next=buildPlan(ps);if(!next){box.querySelector('#plan-status').textContent='Pas assez de données pour recalculer.';return;}draft=next;onDirty(true);draw();};
 box.querySelector('#plan-csv').onclick=()=>download('programme-'+session.code+'.csv',planCsv(draft),'text/csv;charset=utf-8');
 box.querySelector('#plan-save').onclick=async()=>{const surface=box.closest('main');if(surface)surface.inert=true;const controls=[...box.querySelectorAll('button,textarea')],disabled=controls.map(el=>el.disabled);controls.forEach(el=>el.disabled=true);try{await save(normalizePlan(draft));onDirty(false);box.querySelector('#plan-status').textContent='Programme enregistré.';}catch(e){box.querySelector('#plan-status').textContent=e.message;}finally{if(surface)surface.inert=false;controls.forEach((el,i)=>el.disabled=disabled[i]);}};
 }
 draw();
}
